demo.program:
// PUMA purpose demo (simulated model)
console.log('micro-CT -> voxels -> properties');
console.log('PUMA: image in, material data out');

// Segmentation demo (simulated model)
var vox=1000, fiber=450, matrix=200, pore=350;
console.log('voxels: fiber '+(fiber/10)+'%, matrix '+(matrix/10)+'%, pore '+(pore/10)+'%');
console.log('segmented '+vox+' voxels');

// Porosity demo (simulated model)
var void_vox=350, total=1000;
var phi=void_vox/total;
console.log('porosity='+phi.toFixed(2)+' ('+(phi*100).toFixed(0)+'% void)');
console.log('insulation up, strength down: the trade');

// Maxwell conductivity demo (simulated model)
var ks=1.2, kg=0.03, phi=0.35;
var ke=kg*(2*kg+ks+2*phi*(ks-kg))/(2*kg+ks-phi*(ks-kg));
console.log('keff='+ke.toFixed(4)+' W/mK at porosity '+phi);

// Kozeny-Carman demo (simulated model)
var phi=0.35, d=20e-6;
var k=phi*phi*phi*d*d/(180*(1-phi)*(1-phi));
console.log('permeability='+k.toExponential(2)+' m^2');
console.log('gas outflow modeled');

// PICA facts demo (simulated model)
var pica={density:270,fiber:'carbon',resin:'phenolic'};
console.log('PICA density ~'+pica.density+' kg/m^3');
console.log(pica.fiber+' + '+pica.resin+': the reference');

// Recession demo (simulated model)
var rate=0.5, t=120;
console.log('recession '+(rate*t/1000).toFixed(2)+' m over '+t+'s');
console.log('sacrificial cooling quantified');

// Stiffness estimate demo (simulated model)
var vf=0.45, Ef=230e9;
var E=vf*Ef*0.3;
console.log('estimated E='+(E/1e9).toFixed(1)+' GPa');
console.log('microstructure -> stiffness');

// Tortuosity demo (simulated model)
var straight=100, actual=165;
console.log('tortuosity='+(actual/straight).toFixed(2));
console.log('crooked paths slow transport');

// Arc-jet validation demo (simulated model)
var pred=2.1, meas=2.0;
console.log('predicted '+pred+'mm measured '+meas+'mm');
console.log(Math.abs(pred-meas)<0.3?'VALIDATED':'RECALIBRATE');

// Phase evolution demo (simulated model)
var ph={resin:40,char:10,pore:50};
ph.char+=30;ph.resin-=30;
console.log('char '+ph.char+'% resin '+ph.resin+'% (heated)');
console.log('phases tracked');

// Pipeline demo (simulated model)
var p=['image','segment','properties','response','validate'];
for(var i=0;i<p.length;i++){console.log((i+1)+'. '+p[i]);}
console.log('voxels -> vehicle margins');

// Screening demo (simulated model)
var concepts=[['A',0.8],['B',1.4],['C',0.6]];
for(var i=0;i<concepts.length;i++){console.log(concepts[i][0]+': score '+concepts[i][1]+' '+(concepts[i][1]>1?'PURSUE':'drop'));}
console.log('PUMA screened '+concepts.length+' concepts');

// Weave demo (simulated model)
var cell={x:8,y:8,z:4};
console.log('weave unit cell '+cell.x+'x'+cell.y+'x'+cell.z+'mm');
console.log('engineered porosity analyzed');

// PUMA workflow demo (simulated model)
var w=['coupon','micro-CT','PUMA','response code','arc-jet','flight'];
for(var i=0;i<w.length;i++){console.log((i+1)+'. '+w[i]);}
console.log('PUMA workflow complete');
